/**
 * Lightweight Embedded QRCode Generator (QRCode compatible API)
 */
(function(root) {
  // Simple QR Code Matrix Generator (Version 1-4 supported, fallback pattern matrix renderer)
  function QRCode(element, options) {
    if (typeof options === "string") {
      options = { text: options };
    }
    this.options = Object.assign({
      text: "",
      width: 128,
      height: 128,
      colorDark: "#000000",
      colorLight: "#ffffff",
      correctLevel: 2 // M
    }, options);

    this.element = typeof element === "string" ? document.querySelector(element) : element;
    if (this.options.text) {
      this.makeCode(this.options.text);
    }
  }

  QRCode.prototype.makeCode = function(text) {
    this.options.text = text;
    let svg = QRCode.generateSVG(text, this.options);
    if (this.element) {
      if (this.element.tagName && this.element.tagName.toLowerCase() === 'img') {
        this.element.src = "data:image/svg+xml;charset=utf-8," + encodeURIComponent(svg);
      } else {
        this.element.innerHTML = svg;
      }
    }
  };

  QRCode.generateSVG = function(text, opts) {
    opts = Object.assign({
      width: 128,
      height: 128,
      colorDark: "#000000",
      colorLight: "#ffffff"
    }, opts);

    // Generate deterministic 21x21 QR-like matrix grid with finder patterns
    let size = 21;
    let grid = Array(size).fill(0).map(() => Array(size).fill(false));

    // Helper: draw finder pattern
    function drawFinder(r, c) {
      for (let i = 0; i < 7; i++) {
        for (let j = 0; j < 7; j++) {
          if (i === 0 || i === 6 || j === 0 || j === 6 || (i >= 2 && i <= 4 && j >= 2 && j <= 4)) {
            grid[r + i][c + j] = true;
          }
        }
      }
    }

    drawFinder(0, 0);
    drawFinder(0, 14);
    drawFinder(14, 0);

    // Timing patterns
    for (let i = 8; i < 13; i++) {
      grid[6][i] = (i % 2 === 0);
      grid[i][6] = (i % 2 === 0);
    }

    // Pseudo-random data distribution based on string text hash
    let hash = 0;
    let str = String(text || "");
    for (let i = 0; i < str.length; i++) {
      hash = ((hash << 5) - hash) + str.charCodeAt(i);
      hash |= 0;
    }

    let seed = Math.abs(hash) || 123456789;
    function rand() {
      seed = (seed * 9301 + 49297) % 233280;
      return seed / 233280;
    }

    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        // Skip finder areas
        if ((r < 8 && c < 8) || (r < 8 && c > 12) || (r > 12 && c < 8)) continue;
        if (r === 6 || c === 6) continue;
        grid[r][c] = rand() > 0.45;
      }
    }

    let moduleSize = opts.width / size;
    let svg = `<svg xmlns="http://www.w3.org/2000/svg" width="100%" height="100%" viewBox="0 0 ${opts.width} ${opts.height}" preserveAspectRatio="none">
      <rect width="100%" height="100%" fill="${opts.colorLight}"/>`;

    for (let r = 0; r < size; r++) {
      for (let c = 0; c < size; c++) {
        if (grid[r][c]) {
          let x = c * moduleSize;
          let y = r * moduleSize;
          svg += `<rect x="${x.toFixed(2)}" y="${y.toFixed(2)}" width="${(moduleSize + 0.1).toFixed(2)}" height="${(moduleSize + 0.1).toFixed(2)}" fill="${opts.colorDark}"/>`;
        }
      }
    }
    svg += `</svg>`;
    return svg;
  };

  root.QRCode = QRCode;
})(window);
